def resolve_columns(selector, headers):
    """Resolve the common selector syntax (indices, names, inclusive ranges)."""
    n = len(headers)

    def one(part):
        part = part.strip()
        if part.startswith('"') and part.endswith('"'):
            part = part[1:-1]
        try:
            i = int(part)
            if i < 0:
                i += n
        except ValueError:
            try:
                i = headers.index(part)
            except ValueError:
                raise ValueError("column not found: " + part)
        if i < 0 or i >= n:
            raise ValueError("column index out of bounds: " + part)
        return i

    result = []
    for token in selector.split(","):
        token = token.strip()
        if ":" in token:
            left, right = token.split(":", 1)
            a = 0 if left == "" else one(left)
            b = n - 1 if right == "" else one(right)
            step = 1 if a <= b else -1
            indices = list(range(a, b + step, step))
        else:
            indices = [one(token)]
        result.extend(indices)
    return result


